-- bajet-kahwin  id=9f737846-4fe2-4cfd-ae61-b5823cc9935c  updated_at was 2026-08-25T10:13:21.643Z
update articles set
  title = 'Bajet Kahwin 2026: Apa yang Boleh Diharga Tepat, dan Apa yang Tidak',
  excerpt = 'Kebanyakan senarai bajet kahwin memberi anda angka untuk setiap baris. Kebanyakan angka itu tidak boleh disahkan. Ini cara membina bajet yang tidak runtuh.',
  content = '{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Bajet kahwin dibina daripada dua jenis nombor, dan mencampurkan kedua-duanya adalah punca kebanyakan bajet tersasar. Ada kos yang ditetapkan oleh pihak berkuasa dan tersiar secara rasmi, iaitu sewa dewan dan yuran kursus. Ada kos yang ditetapkan oleh vendor seorang demi seorang, dan tiada kadar rasminya di mana-mana. Yang pertama boleh dikunci hari ini. Yang kedua hanya boleh dianggarkan selepas anda pegang sebut harga bertulis.","type":"text"}]},{"type":"figureBlock","attrs":{"alt":"Kad tajuk artikel bertajuk Bajet Kahwin 2026, apa yang boleh diharga tepat dan apa yang tidak, di atas latar krim dengan garis tembaga.","src":"https://images.hellokahwin.com/inspire/bajet-kahwin/1787652788266-c6-2-a4-bajet-kahwin-cover/high.webp","data-caption":"Grafik: HelloKahwin","data-caption-url":null}},{"type":"paragraph","content":[{"text":"Artikel ini memisahkan kedua-duanya, dan tidak memberi anda angka untuk perkara yang kami tidak dapat sahkan.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Kenapa kami tidak menyiarkan jadual \"kos kahwin lengkap\"","type":"text"}]},{"type":"paragraph","content":[{"text":"Cari \"kos kahwin\" dan anda akan jumpa jadual kemas: katering sekian seorang, pelamin sekian, fotografi sekian. Angka-angka itu kelihatan berwibawa kerana ia disusun dalam jadual.","type":"text"}]},{"type":"paragraph","content":[{"text":"Masalahnya, hampir tiada satu pun daripadanya boleh dijejaki ke sumber asal. Katering, pelamin, fotografi dan baju ditetapkan oleh perniagaan individu yang tidak tertakluk kepada mana-mana jadual fi. Dua katerer di jalan yang sama boleh berbeza dua kali ganda, dan tiada pihak berkuasa yang menerbitkan purata.","type":"text"}]},{"type":"paragraph","content":[{"text":"Jadi kami menyiarkan yang boleh disahkan, dan menerangkan cara mendapatkan yang selebihnya daripada sumber sebenar, iaitu sebut harga anda sendiri.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Bahagian yang boleh dikunci hari ini","type":"text"}]},{"type":"heading","attrs":{"level":3},"content":[{"text":"Sewa dewan","type":"text"}]},{"type":"paragraph","content":[{"text":"Ini bahagian bajet yang paling telus, dan biasanya paling rendah daripada yang disangka orang.","type":"text"}]},{"type":"paragraph","content":[{"text":"Majlis perbandaran di Selangor menyiarkan senarai kadar penuh. Julatnya luas:","type":"text"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Pihak berkuasa","type":"text"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Kadar majlis perkahwinan","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"MP Sepang","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"RM100 hingga RM250 sejam bagi dewan komuniti, ikut saiz dan sama ada berhawa dingin; Dewan Serbaguna Kelab Komuniti RM1,500 empat jam","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"MB Diraja Klang","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"RM60 hingga RM200 sejam bagi dewan komuniti; Dewan Hamzah RM3,450 enam jam","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"MB Petaling Jaya","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"RM160 hingga RM450 satu sesi enam jam bagi dewan komuniti; Dewan Banquet RM5,000 empat jam","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"MB Subang Jaya","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"RM880 hingga RM3,200 satu sesi lapan jam, ikut kategori A hingga E","type":"text"}]}]}]}]},{"type":"paragraph","content":[{"text":"Untuk bajet, gunakan jumlah, bukan kadar sewa. Kebanyakan majlis mengenakan penghawa dingin, kebersihan, elektrik dan sampah secara berasingan, dan sesi persiapan selalunya dikira sebagai tempahan kedua.","type":"text"}]},{"type":"paragraph","content":[{"text":"Contoh yang boleh dikira sepenuhnya daripada senarai rasmi: dewan komuniti MBPJ pada RM160 satu sesi enam jam, dengan penghawa dingin RM100 sejam dan kebersihan serta elektrik RM100 tetap, menjadi RM860 untuk satu sesi. Cagaran RM200 di atas itu, dan ia dipulangkan.","type":"text"}]},{"type":"paragraph","content":[{"text":"Perincian penuh setiap majlis perbandaran ada dalam panduan harga sewa dewan kami, dan senarai ","type":"text"},{"text":"dewan kahwin murah","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"/artikel/idea-dan-nasihat/dewan-kahwin","class":null,"target":"_blank"}}]},{"text":" di Selangor dan KL boleh membantu anda memilih.","type":"text"}]},{"type":"paragraph","content":[{"text":"(Sumber: senarai kadar rasmi MBPJ 2024, MBSJ Februari 2024, MBDK 2024, MP Sepang berkuat kuasa 1 Oktober 2022, semuanya disemak 25 Ogos 2026.)","type":"text","marks":[{"type":"italic"}]}]},{"type":"heading","attrs":{"level":3},"content":[{"text":"Cagaran","type":"text"}]},{"type":"paragraph","content":[{"text":"Cagaran bukan kos, tetapi ia wang yang perlu ada sebelum majlis, dan ia kerap tertinggal daripada bajet.","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"MBSJ: 50% daripada jumlah tempahan","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"MB Diraja Klang, majlis kahwin: cagaran dewan RM200 hingga RM300, kebersihan RM150, keselamatan RM150, peralatan RM200, iaitu RM700 hingga RM800 kesemuanya","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"MBPJ dewan komuniti: RM200 hingga RM350","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"MBPJ Dewan Banquet: RM2,000, tunai atau bank draf sahaja","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Letakkan ini sebagai baris berasingan dalam bajet, ditanda \"dipulangkan\". Kalau ia dicampur dengan kos sebenar, anda akan tersilap kira dua kali.","type":"text"}]},{"type":"heading","attrs":{"level":3},"content":[{"text":"Kursus pra-perkahwinan","type":"text"}]},{"type":"paragraph","content":[{"text":"Yuran Kursus Pra Perkahwinan Islam di Selangor ialah RM100 seorang, merangkumi makan minum dan alat tulis, mengikut soalan lazim rasmi Jabatan Agama Islam Selangor. Untuk pasangan, RM200.","type":"text"}]},{"type":"paragraph","content":[{"text":"Kadar ini ditetapkan mengikut negeri, jadi semak jabatan agama Islam negeri anda untuk kadar yang tepat. Butiran pendaftaran dan syarat ada dalam panduan ","type":"text"},{"text":"kursus kahwin","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"/artikel/idea-dan-nasihat/kursus-kahwin","class":null,"target":"_blank"}}]},{"text":" kami.","type":"text"}]},{"type":"paragraph","content":[{"text":"(Sumber: soalan lazim Jabatan Agama Islam Selangor, jais.gov.my, disemak 25 Ogos 2026.)","type":"text","marks":[{"type":"italic"}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Bahagian yang perlu sebut harga","type":"text"}]},{"type":"paragraph","content":[{"text":"Untuk baris-baris ini kami tidak menyiarkan angka, kerana tiada kadar rasmi wujud dan menyalin angka blog akan menjadikan bajet anda lebih teruk, bukan lebih baik.","type":"text"}]},{"type":"paragraph","content":[{"text":"Katering ialah kos terbesar dalam hampir setiap majlis, dan ia bergantung pada bilangan tetamu, jenis hidangan dan sama ada dewan membenarkan katerer pilihan anda. Minta sebut harga bertulis yang menyatakan bilangan tetamu, bilangan meja, menu, dan sama ada meja, kerusi, alas dan pelayan termasuk.","type":"text"}]},{"type":"paragraph","content":[{"text":"Untuk pelamin dan hiasan, minta sebut harga yang menyatakan berapa jam kru perlu untuk memasang, kerana jam itu mungkin dicaj oleh dewan sebagai masa persiapan.","type":"text"}]},{"type":"paragraph","content":[{"text":"Untuk fotografi dan videografi, sahkan berapa jam liputan dan berapa lama sebelum gambar diserahkan.","type":"text"}]},{"type":"paragraph","content":[{"text":"Untuk baju pengantin, sewa dan tempahan jahit adalah dua bajet yang berbeza sepenuhnya.","type":"text"}]},{"type":"paragraph","content":[{"text":"Kad jemputan dan cenderahati bergantung terus pada bilangan tetamu. Idea untuk bahagian ini ada dalam senarai ","type":"text"},{"text":"goodies kahwin","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"/artikel/hiasan-dekorasi/goodies-kahwin","class":null,"target":"_blank"}}]},{"text":" kami.","type":"text"}]},{"type":"paragraph","content":[{"text":"Cara mendapatkan angka yang boleh dipercayai untuk lima baris ini sama sahaja: tiga sebut harga bertulis untuk setiap satu, daripada vendor sebenar, dengan bilangan tetamu anda sendiri. Tiga sebut harga memberitahu anda julat pasaran di kawasan anda, yang mana-mana purata dalam talian tidak boleh lakukan.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Cara menyusun bajet supaya ia tidak runtuh","type":"text"}]},{"type":"paragraph","content":[{"text":"Mulakan dengan bilangan tetamu, bukan dengan jumlah wang. Bilangan tetamu menentukan saiz dewan, jumlah katering, bilangan kad dan bilangan cenderahati. Ia satu-satunya nombor yang menggerakkan semua baris lain sekali gus, dan ia juga satu-satunya yang benar-benar dalam kawalan anda.","type":"text"}]},{"type":"paragraph","content":[{"text":"Kunci kos tetap dahulu. Dewan, cagaran dan kursus boleh diketahui dengan tepat sekarang. Tolakkan daripada jumlah bajet, dan yang tinggal itulah wang sebenar untuk katering dan hiasan.","type":"text"}]},{"type":"paragraph","content":[{"text":"Simpan 10% yang tidak diperuntukkan. Bukan untuk perkara yang anda lupa, tetapi untuk perkara yang berubah: bilangan tetamu naik, dewan mengenakan jam persiapan tambahan, cuti am diisytiharkan pada tarikh anda dan kadar berganda.","type":"text"}]},{"type":"paragraph","content":[{"text":"Semak semula pada tiga bulan. Itu titik terakhir yang munasabah untuk memotong sesuatu tanpa kehilangan deposit.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Di mana penjimatan sebenar berada","type":"text"}]},{"type":"paragraph","content":[{"text":"Berdasarkan kadar rasmi yang boleh disahkan, tiga keputusan menggerakkan angka lebih daripada apa-apa senarai tip:","type":"text"}]},{"type":"paragraph","content":[{"text":"Tarikh dahulu. MBPJ mengenakan bayaran dua kali ganda pada cuti am. MBSJ menaikkan kategori E daripada RM880 ke RM1,440 pada cuti am. Memindahkan majlis daripada hari cuti ke hujung minggu biasa menjimatkan ratusan hingga ribuan ringgit tanpa mengubah apa-apa lagi tentang majlis anda.","type":"text"}]},{"type":"paragraph","content":[{"text":"Kemudian penghawa dingin. Pada RM100 sejam di MBPJ atau RM60 sejam di Klang, ini boleh menjadi kos kedua terbesar selepas katering di dewan komuniti. Majlis pagi di dewan yang berkipas dan berbumbung tinggi adalah keputusan bajet yang sah.","type":"text"}]},{"type":"paragraph","content":[{"text":"Dan bilangan jam. Kadar sejam bermakna majlis enam jam kos 25% kurang daripada majlis lapan jam. Aturcara yang ketat menjimatkan wang sebenar, bukan sekadar mengelakkan tetamu bosan.","type":"text"}]},{"type":"paragraph","content":[{"text":"Ketiga-tiga ini keputusan tentang masa, bukan tentang memotong kualiti, dan itu sebabnya ia menjimatkan tanpa menjejaskan majlis.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Ringkasnya","type":"text"}]},{"type":"paragraph","content":[{"text":"Bina bajet kahwin anda dalam dua lajur. Lajur pertama ialah kos yang mempunyai kadar rasmi tersiar, iaitu dewan, cagaran dan kursus, dan boleh dikunci hari ini dengan tepat. Lajur kedua ialah kos vendor, dan setiap satu memerlukan tiga sebut harga bertulis sebelum ia layak masuk ke dalam bajet.","type":"text"}]},{"type":"paragraph","content":[{"text":"Bajet yang runtuh biasanya runtuh kerana lajur kedua diisi dengan angka yang disalin daripada internet. Angka itu bukan salah semata-mata; ia untuk majlis orang lain, di kawasan lain, pada tahun lain.","type":"text"}]},{"type":"paragraph","content":[{"text":"Semua kadar rasmi dalam artikel ini disemak pada 25 Ogos 2026 dan berubah dari semasa ke semasa. Sahkan dengan pihak berkuasa berkenaan sebelum anda kunci apa-apa angka.","type":"text"}]}]}'::jsonb,
  cover_image_url = 'https://images.hellokahwin.com/inspire/bajet-kahwin/1787652788266-images-s-keluarga-payung-kuning-mohd-hasan.jpg',
