-- borang-nikah  id=ce836c00-fb6c-4875-b438-bd42216518d7  updated_at was 2026-08-25T10:11:29.872Z
update articles set
  title = 'Borang Nikah: Borang Mana, Isi Apa, Hantar Ke Mana',
  excerpt = 'Borang nikah bukan satu borang. Ini senarai borang yang diwartakan di Perak, isi kandungan borang permohonan, tempoh hantar di Selangor dan Pulau Pinang, dan sistem mana yang negeri anda guna.',
  content = '{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Borang yang anda cari hampir pasti Borang Permohonan Untuk Kebenaran Berkahwin. Lelaki mengisi satu, perempuan mengisi satu, dan kedua-duanya dihantar kepada Pendaftar bagi kariah masjid tempat pihak perempuan bermastautin. Yang selebihnya (kebenaran, catatan daftar, perakuan nikah, kad nikah) dikeluarkan oleh pejabat, bukan diisi oleh anda.","type":"text"}]},{"type":"figureBlock","attrs":{"alt":"Grafik enam borang nikah yang diwartakan di Perak disusun mendatar mengikut turutan, daripada Borang 1 permohonan kebenaran berkahwin hingga Borang 6 kad nikah, setiap satu dengan fi bercetak di sebelahnya.","src":"https://images.hellokahwin.com/inspire/borang-nikah/1787652677828-cover-borang-nikah/high.webp","data-caption":"Borang 1 hingga 6 seperti disenaraikan dalam Pk. P.U. 30, Warta Kerajaan Negeri Perak, 1 Jun 2013. — Grafik: HelloKahwin","data-caption-url":null}},{"type":"paragraph","content":[{"text":"Setiap negeri mewartakan set borangnya sendiri, dengan tempoh dan fi sendiri. Perak, Selangor dan Pulau Pinang menerbitkan butiran itu secara terbuka, jadi ketiga-tiga negeri inilah yang dipetik di bawah.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Borang nikah bukan satu borang","type":"text"}]},{"type":"paragraph","content":[{"text":"Perak mewartakan sembilan belas borang dalam Kaedah-Kaedah Undang-Undang Keluarga Islam (Borang dan Fi) 2013, Pk. P.U. 30, bertarikh 1 Jun 2013. Enam yang pertama ialah yang menyentuh perkahwinan:","type":"text"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Borang","type":"text"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Untuk apa","type":"text"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Seksyen","type":"text"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Fi bercetak","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Borang 1","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Permohonan Untuk Kebenaran Berkahwin","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"16","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"RM1.00","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Borang 2","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Kebenaran Berkahwin","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"17","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"RM5.00","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Borang 3","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Kebenaran Berkahwin oleh Hakim Syarie","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"18","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"RM10.00","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Borang 4","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Butir-butir untuk dicatat dalam Daftar Perkahwinan","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"22","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Tiada fi bercetak","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Borang 5","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Perakuan Nikah","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"26","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"RM15.00","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Borang 6","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Kad Nikah","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"26","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"RM20.00","type":"text"}]}]}]}]},{"type":"paragraph","content":[{"text":"Anda mengisi Borang 1. Borang 2 dikeluarkan kepada anda kalau permohonan diluluskan. Borang 3 menggantikannya kalau kes anda kena rujuk kepada Hakim Syarie: di bawah umur, janda yang tersabit oleh subseksyen 14(3), atau perempuan yang tiada wali dari nasab. Borang 4 dan 5 diisi selepas akad. Lafaz taklik dicetak dalam Borang 4 dan Borang 5.","type":"text"}]},{"type":"paragraph","content":[{"text":"Kaedah 4 Pk. P.U. 30 menyebut ketidakpatuhan dengan mana-mana borang yang ditetapkan tidak membatalkan sesuatu prosiding, tetapi Mahkamah hendaklah mengarahkan pihak itu meminda atau membetulkan borang berkenaan.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Apa yang ada dalam borang permohonan","type":"text"}]},{"type":"paragraph","content":[{"text":"Borang 1 Perak dibahagikan kepada tujuh bahagian, A hingga G. Bahagian A hingga E diisi oleh pihak pemohon (Bahagian D ditandatangani oleh wali). Bahagian F dan G untuk pejabat.","type":"text"}]},{"type":"heading","attrs":{"level":3},"content":[{"text":"A. Maklumat pemohon","type":"text"}]},{"type":"paragraph","content":[{"text":"Nama, nombor kad pengenalan atau pasport, tarikh lahir, umur, alamat semasa, bangsa, kewarganegaraan, status (teruna / duda / beristeri / anak dara / janda / balu / thayyib), nombor bil pendaftaran perceraian atau kematian jika berkenaan, kelulusan akademik, pekerjaan, pendapatan, tarikh memeluk Islam jika berkenaan, dan nombor telefon.","type":"text"}]},{"type":"heading","attrs":{"level":3},"content":[{"text":"B. Maklumat pasangan","type":"text"}]},{"type":"paragraph","content":[{"text":"Medan yang sama sekali lagi, untuk bakal pasangan anda.","type":"text"}]},{"type":"heading","attrs":{"level":3},"content":[{"text":"C. Maklumat perkahwinan","type":"text"}]},{"type":"paragraph","content":[{"text":"Tarikh cadangan akad dalam Hijrah dan Masihi, alamat tempat akad, dan tiga medan wang yang berasingan: mas kahwin, belanja hantaran, dan pemberian lain jika ada. Ketiga-tiganya perkara berbeza, dan borang memang mengasingkannya. Kadar mas kahwin minimum berbeza mengikut negeri, dan itu dihuraikan dalam ","type":"text"},{"text":"mas kahwin ikut negeri","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"/artikel/hantaran-mas-kahwin/mas-kahwin-ikut-negeri","class":null,"target":"_blank"}}]},{"text":".","type":"text"}]},{"type":"heading","attrs":{"level":3},"content":[{"text":"D. Maklumat wali, bagi pemohon perempuan","type":"text"}]},{"type":"paragraph","content":[{"text":"Nama, kad pengenalan, tarikh lahir, umur, alamat, hubungan wali dengan pemohon, dan tandatangan wali.","type":"text"}]},{"type":"heading","attrs":{"level":3},"content":[{"text":"E. Pengakuan pemohon","type":"text"}]},{"type":"paragraph","content":[{"text":"Ayat yang anda tandatangani berbunyi: \"Saya dengan ini sesungguhnya mengaku bahawa segala akuan atau pernyataan di atas adalah benar dan sekiranya mana-mana akuan atau penyataan itu palsu maka saya melakukan suatu kesalahan yang boleh dihukum di bawah seksyen 38 Enakmen Undang-Undang Keluarga Islam (Perak) 2004.\"","type":"text"}]},{"type":"heading","attrs":{"level":3},"content":[{"text":"F dan G, untuk pejabat","type":"text"}]},{"type":"paragraph","content":[{"text":"Bahagian F ialah tempat Pendaftar mengesahkan status anda dan mencatat nombor bil Kebenaran Mahkamah Syariah jika ada. Bahagian G ialah tempat permohonan diluluskan atau tidak diluluskan.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Bila kena hantar","type":"text"}]},{"type":"paragraph","content":[{"text":"Perak mencetak peringatannya terus atas borang: \"Permohonan ini hendaklah dikemukakan kepada Pendaftar sekurang-kurangnya 7 hari dari tarikh perkahwinan.\"","type":"text"}]},{"type":"paragraph","content":[{"text":"Selangor meletakkannya dalam enakmen. Seksyen 16(3) Enakmen Undang-Undang Keluarga Islam (Negeri Selangor) 2003: permohonan tiap-tiap satu pihak hendaklah disampaikan kepada Pendaftar sekurang-kurangnya tujuh hari sebelum tarikh yang dicadangkan, tetapi Pendaftar boleh membenarkan masa yang lebih singkat dalam kes tertentu.","type":"text"}]},{"type":"paragraph","content":[{"text":"Pulau Pinang menetapkan tempoh di kedua-dua hujung. Menurut e-Munakahat, Jabatan Hal Ehwal Agama Islam Pulau Pinang, borang boleh diisi seawal 90 hari dari tarikh akad nikah, dan selewat-lewatnya 14 hari bagi warganegara Malaysia atau 21 hari bagi warganegara asing sebelum tarikh akad. Kebenaran berkahwin dikeluarkan dalam masa tujuh hari bekerja dari permohonan lengkap diterima.","type":"text"}]},{"type":"paragraph","content":[{"text":"Tujuh hari itu had minimum, bukan sasaran yang selesa. Kalau dokumen anda tidak lengkap, permohonan belum dianggap diterima.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Dokumen: contoh senarai penuh","type":"text"}]},{"type":"paragraph","content":[{"text":"Pulau Pinang menerbitkan senarai semaknya, dikemas kini Mei 2023, dan ia dipecahkan mengikut keadaan pemohon: dua belas item untuk pemohon lelaki warganegara, sembilan belas untuk pemohon perempuan, lapan untuk bukan warganegara, dan lima untuk pemastautin tetap.","type":"text"}]},{"type":"paragraph","content":[{"text":"Yang biasa bagi kedua-dua pihak: kad pengenalan pemohon (asal dan salinan), kad pengenalan pasangan (salinan), sijil Kursus Praperkahwinan Islam, dan keputusan ujian saringan HIV daripada Klinik Kesihatan Kerajaan sahaja, sah laku enam bulan.","type":"text"}]},{"type":"paragraph","content":[{"text":"Yang ditambah bagi pemohon perempuan: kad pengenalan wali, surat kebenaran berkahwin pihak lelaki, dan dokumen yang menunjukkan wujud hubungan nasab wali dengan pemohon, iaitu surat perakuan nikah ibu bapa kandung, surat perakuan perceraian ibu bapa kandung, sijil kematian wali, atau sijil kelahiran pemohon dan wali jika walinya selain bapa atau datuk.","type":"text"}]},{"type":"paragraph","content":[{"text":"Yang ditambah mengikut keadaan: surat akuan perceraian bagi duda, surat perakuan perceraian bagi janda, sijil kematian dan surat perakuan nikah bagi balu, surat kelulusan bagi anggota tentera atau polis, dan perintah Mahkamah Syariah bagi perkahwinan poligami, bawah umur, janda berhias atau wali Raja.","type":"text"}]},{"type":"paragraph","content":[{"text":"Dua borang tambahan yang mudah terlepas pandang di Pulau Pinang. Borang Pengesahan Anak Qaryah, jika alamat tempat tinggal anda berbeza daripada alamat kad pengenalan dalam negeri yang sama. Dan Borang Akuan Pengesahan Mastautin, jika kad pengenalan anda negeri lain tetapi anda bermastautin di Pulau Pinang melebihi empat bulan.","type":"text"}]},{"type":"paragraph","content":[{"text":"Satu perkara yang berbaloi diambil kira: e-Munakahat menyatakan pemohon yang mengikuti Kursus Praperkahwinan Islam di Pulau Pinang dikecualikan daripada temuduga. Butiran kursus ada dalam ","type":"text"},{"text":"kursus kahwin","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"/artikel/idea-dan-nasihat/kursus-kahwin","class":null,"target":"_blank"}}]},{"text":".","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Berapa kena bayar","type":"text"}]},{"type":"paragraph","content":[{"text":"Pulau Pinang menyenaraikan RM75.00 bagi pasangan yang melangsungkan akad nikah dalam negeri, dan memecahkannya: RM5.00 surat kebenaran berkahwin, RM10.00 sijil nikah, RM60.00 kad nikah pintar. Bagi permohonan kebenaran berkahwin untuk akad di luar Pulau Pinang, RM5.00. Bayaran saguhati akad nikah RM250.00 dibayar pada hari majlis akad nikah.","type":"text"}]},{"type":"paragraph","content":[{"text":"Ujian saringan HIV pula percuma, dan borangnya percuma, tetapi hanya di Klinik Kesihatan Kerajaan.","type":"text"}]},{"type":"paragraph","content":[{"text":"Perak mencetak fi pada borang itu sendiri, seperti dalam jadual di atas. Kalau anda membandingkan dua negeri, banding perkara yang sama: RM5 kebenaran berkahwin di Pulau Pinang bersamaan Borang 2 Perak, yang juga RM5.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Sistem mana yang negeri anda guna","type":"text"}]},{"type":"paragraph","content":[{"text":"SPPIM, Sistem Pengurusan Perkahwinan Islam Malaysia, dibangunkan oleh Jabatan Kemajuan Islam Malaysia. Versi 2.0 dilancarkan pada 13 September 2025 oleh Perdana Menteri di Sunway Hotel Big Box, Johor Bahru. Modulnya termasuk kursus praperkahwinan dalam talian, permohonan pendaftaran perkahwinan dalam talian, aplikasi mudah alih MySPPIM, dan capaian sijil nikah digital.","type":"text"}]},{"type":"paragraph","content":[{"text":"Tetapi ia bukan satu sistem untuk seluruh negara. Dalam satu berita bertarikh 24 April 2026, JAKIM melaporkan pembentangan kertas cadangan pelaksanaan SPPIM di Kelantan, Pahang, Pulau Pinang, Sabah dan Sarawak. Menurut berita itu, kelima-lima negeri berkenaan masih menggunakan sistem aplikasi kendiri masing-masing. Pembentangan itu dibuat pada 16 April 2026 dalam mesyuarat yang dipengerusikan Menteri Digital.","type":"text"}]},{"type":"paragraph","content":[{"text":"Maknanya untuk anda: kalau anda di salah satu daripada lima negeri itu, portal negeri anda yang betul, bukan SPPIM. Pulau Pinang menggunakan e-Munakahat. Sabah menghalakan pemohon ke Portal ePerkahwinan JHEAINS. Johor, di pihak yang lain, menghalakan permohonan pendaftaran nikah ke SPPIM melalui laman Jabatan Agama Islam Negeri Johor.","type":"text"}]},{"type":"paragraph","content":[{"text":"Satu nota kecil yang menjimatkan masa: pada 24 Ogos 2026, alamat ","type":"text"},{"text":"sppim.gov.my","type":"text","marks":[{"type":"code"}]},{"text":" tanpa ","type":"text"},{"text":"www","type":"text","marks":[{"type":"code"}]},{"text":" tidak menyelesai. Alamat yang berfungsi ialah ","type":"text"},{"text":"www.sppim.gov.my","type":"text","marks":[{"type":"code"}]},{"text":".","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Kalau pengantin lelaki dan perempuan berlainan negeri","type":"text"}]},{"type":"paragraph","content":[{"text":"Enakmen Selangor menjawabnya di tiga tempat.","type":"text"}]},{"type":"paragraph","content":[{"text":"Seksyen 16(1): permohonan dihantar kepada Pendaftar bagi kariah masjid tempat pihak perempuan bermastautin, dan alamat itulah yang menentukan pejabat mana yang memimpin urusan.","type":"text"}]},{"type":"paragraph","content":[{"text":"Seksyen 16(2): kalau pihak lelaki bermastautin di kariah masjid berlainan, atau di mana-mana negeri lain, permohonannya hendaklah mengandungi atau disertai kenyataan daripada Pendaftar kariah masjidnya sendiri, atau daripada pihak berkuasa yang hak bagi negeri itu, yang mengesahkan perkara dalam permohonan itu benar setakat yang dapat dipastikan.","type":"text"}]},{"type":"paragraph","content":[{"text":"Seksyen 20(1) dan 20(3): akad hendaklah dilangsungkan dalam kariah masjid tempat pihak perempuan bermastautin, melainkan kebenaran diberi untuk tempat lain di bawah seksyen 17 atau 18.","type":"text"}]},{"type":"paragraph","content":[{"text":"Jadi urutannya: pihak lelaki dapatkan surat kebenaran daripada pejabat agama negerinya, bawa ke pejabat pihak perempuan, dan pejabat itu yang mengeluarkan kebenaran berkahwin.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Sumber","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Kaedah-Kaedah Undang-Undang Keluarga Islam (Borang dan Fi) 2013, Pk. P.U. 30. Warta Kerajaan Negeri Perak, Jil. 66, Tambahan No. 13, 1 Jun 2013. Kaedah 2, 3 dan 4, Borang 1 hingga 6 dalam Jadual Pertama, dan jadual fi dalam Jadual Kedua. Diterbitkan oleh Jabatan Kehakiman Syariah Negeri Perak. Disemak 24 Ogos 2026.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Enakmen Undang-Undang Keluarga Islam (Negeri Selangor) 2003, seksyen 16, 17, 18, 19 dan 20. Warta Kerajaan Negeri Selangor, 27 Julai 2003, diterbitkan oleh Jabatan Kehakiman Syariah Negeri Selangor. Disemak 24 Ogos 2026.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"e-Munakahat, Jabatan Hal Ehwal Agama Islam Pulau Pinang. Halaman Perkahwinan (Peraturan Am, Ujian Saringan HIV), Senarai Semak Permohonan Kebenaran Berkahwin (kemas kini Mei 2023), dan Kadar Bayaran Urusan Nikah, Cerai dan Ruju'' Negeri Pulau Pinang (kemas kini Mei 2023). Tarikh kemas kini maklumat terakhir di laman: 24 Ogos 2026. Disemak 24 Ogos 2026.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Portal Rasmi JAKIM. \"SPPIM 2.0 Dilancar, Perkukuh Pendigitalan Pengurusan Perkahwinan Islam\"; dan \"Pembentangan Kertas Cadangan Pelaksanaan SPPIM Di Negeri Kelantan, Pahang, Pulau Pinang, Sabah Dan Sarawak\", 24 April 2026. Disemak 24 Ogos 2026.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Jabatan Agama Islam Negeri Johor. Halaman Pendaftaran Nikah, Cerai, Rujuk. Disemak 24 Ogos 2026.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Jabatan Hal Ehwal Agama Islam Negeri Sabah. Halaman Nikah, Cerai & Ruju''. Disemak 24 Ogos 2026.","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Butiran di atas milik negeri yang dinamakan. Perak, Selangor dan Pulau Pinang menerbitkan borang, tempoh dan fi mereka; kebanyakan negeri lain tidak menerbitkannya dalam bentuk yang boleh dipetik. Sahkan dengan Pejabat Agama Daerah anda sebelum anda kunci tarikh majlis.","type":"text"}]}]}'::jsonb,
  cover_image_url = 'https://images.hellokahwin.com/inspire/borang-nikah/1787652677828-images-s-selepas-akad-raja-abd-kadir.jpg',
