-- harga-sewa-dewan-kahwin  id=a6dab084-8ab5-44a5-a28d-a2336f4c9879  updated_at was 2026-08-25T10:12:41.093Z
update articles set
  title = 'Harga Sewa Dewan Kahwin 2026: Kadar Rasmi Majlis Perbandaran, Bukan Anggaran',
  excerpt = 'Kadar sewa dewan majlis perbandaran diambil terus daripada senarai kadar rasmi setiap majlis: berapa yang tersiar, berapa yang sebenarnya keluar dari poket, dan mengapa dua nombor itu jarang sama.',
  content = '{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Sewa dewan majlis perbandaran untuk kenduri kahwin bermula sekitar ","type":"text"},{"text":"RM60 sejam","type":"text","marks":[{"type":"bold"}]},{"text":" di dewan kampung paling kecil dan naik ke ","type":"text"},{"text":"RM3,600 satu sesi","type":"text","marks":[{"type":"bold"}]},{"text":" di dewan serbaguna paling besar. Itu kadar sewa sahaja. Bil sebenar biasanya satu setengah hingga dua kali ganda angka itu, kerana penghawa dingin, kebersihan, hari persiapan dan cagaran semuanya dikira berasingan.","type":"text"}]},{"type":"figureBlock","attrs":{"alt":"Kad tajuk artikel bertajuk Harga Sewa Dewan Kahwin 2026, kadar rasmi majlis perbandaran, di atas latar krim dengan garis tembaga.","src":"https://images.hellokahwin.com/inspire/harga-sewa-dewan-kahwin/1787652742286-c6-2-a1-harga-sewa-dewan-kahwin-cover/high.webp","data-caption":"Grafik: HelloKahwin","data-caption-url":null}},{"type":"paragraph","content":[{"text":"Semua angka di bawah diambil terus daripada senarai kadar rasmi majlis perbandaran masing-masing, dan setiap satu ada tarikh disemaknya. Kami tidak mengambil harga daripada blog atau daripada senarai vendor.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Kenapa \"RM160\" itu bukan RM160","type":"text"}]},{"type":"paragraph","content":[{"text":"Ambil satu contoh sebenar. Senarai kadar Majlis Bandaraya Petaling Jaya meletakkan Dewan PJS 4/19, Taman Indah Jaya pada RM160 satu sesi, dan satu sesi bermakna enam jam, sama ada 8.00 pagi hingga 2.00 petang, atau 5.00 petang hingga 11.00 malam.","type":"text"}]},{"type":"paragraph","content":[{"text":"Di bawah nombor itu, dalam senarai yang sama, ada tiga baris lagi:","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Kebersihan dan elektrik: RM100, tetap","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Penghawa dingin: RM100 sejam","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Cagaran: RM200","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Kalau majlis anda enam jam dan anda mahu dewan itu sejuk, penghawa dingin sahaja RM600. Jadi RM160 tadi sebenarnya RM860, dan anda masih perlu keluarkan RM200 cagaran sebelum boleh masuk. Cagaran itu dipulangkan, tetapi ia tetap wang yang perlu ada dalam akaun pada bulan itu.","type":"text"}]},{"type":"paragraph","content":[{"text":"Inilah sebab paling biasa bajet dewan tersasar. Angka yang tersiar di ruangan \"kadar sewa\" ialah satu baris daripada senarai, bukan jumlah di bawah senarai.","type":"text"}]},{"type":"paragraph","content":[{"text":"(Sumber: senarai kadar tempahan kemudahan MBPJ tahun 2024, masih dokumen kadar terkini di portal rasmi mbpj.gov.my, disemak 25 Ogos 2026.)","type":"text","marks":[{"type":"italic"}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Ikut jam atau ikut sesi, dan kenapa ia penting","type":"text"}]},{"type":"paragraph","content":[{"text":"Majlis perbandaran tidak mengira dengan cara yang sama, jadi dua angka yang nampak serupa boleh bermakna dua bil yang jauh berbeza.","type":"text"}]},{"type":"paragraph","content":[{"text":"MBPJ dan Majlis Bandaraya Subang Jaya menjual blok masa. Anda bayar satu harga untuk enam atau lapan jam, sama ada anda guna habis atau tidak. Majlis Bandaraya Diraja Klang pula mengenakan kadar sejam untuk hampir semua dewannya, jadi dewan yang tersiar pada RM120 sejam menjadi RM960 untuk majlis lapan jam, sebelum apa-apa caj lain.","type":"text"}]},{"type":"paragraph","content":[{"text":"Jangan bandingkan RM160 di Petaling Jaya dengan RM170 di Klang. Yang pertama enam jam; yang kedua satu jam.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Kadar rasmi, ikut pihak berkuasa","type":"text"}]},{"type":"heading","attrs":{"level":3},"content":[{"text":"Majlis Bandaraya Petaling Jaya","type":"text"}]},{"type":"paragraph","content":[{"text":"Senarai MBPJ menyusun dewan komuniti dan balairayanya dalam beberapa lapisan harga, semuanya per sesi enam jam:","type":"text"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Dewan","type":"text"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Sewa satu sesi","type":"text"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Cagaran","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Balairaya PJS 6/3B Kampung Lindungan, Balairaya Seksyen 17/1 dan seangkatan","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"RM160","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"RM200","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Dewan SS 3/14 Taman Sentosa, Dewan SS 21/9 Damansara Utama","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"RM200","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"RM250","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Dewan Jalan 51A/227","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"RM240","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"RM250","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Dewan PJS 1/35 Petaling Utama, Dewan SS 7/28 Kelana Jaya, Dewan Sri Damansara","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"RM250","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"RM250","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Dewan Seksyen 7 Kota Damansara, Dewan Bandar Utama (BU 3)","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"RM350","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"RM350","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Dewan Komuniti Taman Dato Harun","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"RM350","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"RM200","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Dewan Komuniti Damansara Damai","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"RM450","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"RM350","type":"text"}]}]}]}]},{"type":"paragraph","content":[{"text":"Dua dewan MBPJ dikira sejam, bukan sesesi: Dewan Komuniti Bandar Utama 11 dan Dewan D''Kelana, Kelana Jaya, kedua-duanya RM250 sejam berhawa dingin, dengan cagaran RM350.","type":"text"}]},{"type":"paragraph","content":[{"text":"Perhatikan juga baris \"TIADA HAWA DINGIN\" dalam senarai itu. Antara yang bertanda begitu: Balairaya PJS 6/3B Kampung Lindungan, Balairaya Kampung Sungai Kayu Ara, Balairaya SS 3/39 Selera Sukom, Dewan SS 1/19 Kampung Tunku, Dewan Jalan 51A/227 dan Dewan Komuniti Taman Dato Harun. Untuk kenduri tengah hari bulan Mac, itu bukan perkara kecil.","type":"text"}]},{"type":"heading","attrs":{"level":3},"content":[{"text":"Majlis Bandaraya Diraja Klang","type":"text"}]},{"type":"paragraph","content":[{"text":"Klang menyiarkan kadar khusus untuk majlis perkahwinan, berasingan daripada kadar seminar dan sukan. Semuanya sejam:","type":"text"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Kadar majlis perkahwinan","type":"text"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Antara dewannya","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"RM60 sejam","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Dewan Taman Bunga Melor","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"RM80 sejam","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Dewan Kampung Jawa, Dewan Jalan Batu Nilam 15","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"RM92 sejam","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Dewan Berkeley, Dewan Pelabuhan Klang, Dewan Pendamar Indah 2","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"RM115 sejam","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Dewan Sungai Pinang, Dewan Seri Kerayong","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"RM120 sejam","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Dewan Eng Ann, Dewan Sentosa, Dewan Ambang Botanik 2, Dewan Klang Jaya","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"RM170 sejam","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Dewan Meru, Dewan Teluk Pulai, Dewan Pandamaran Jaya, Dewan Bukit Tinggi 2","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"RM200 sejam","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Dewan Ahmad Razali","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"RM1,750 sejam · RM3,450 enam jam · RM7,500 sepuluh jam","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Dewan Hamzah","type":"text"}]}]}]}]},{"type":"paragraph","content":[{"text":"Caj tambahan Klang: persiapan RM23 sejam dan sampah RM100 sehari, sama di setiap dewan. Penghawa dingin RM60 sejam, tetapi hanya di sebahagian dewan. Lebih separuh daripada senarai itu bertanda TIADA di lajur penghawa dingin, yang bermakna dewan itu memang tiada.","type":"text"}]},{"type":"paragraph","content":[{"text":"Cagaran Klang berlapis, dan untuk majlis kahwin ia lebih tinggi daripada majlis lain: cagaran dewan RM200 hingga RM300 dan cagaran keselamatan RM150, kedua-duanya bertanda untuk majlis perkahwinan sahaja; cagaran kebersihan RM150 dan cagaran peralatan RM200. ","type":"text"},{"text":"Jumlahnya RM700 hingga RM800 wang cagaran","type":"text","marks":[{"type":"bold"}]},{"text":" untuk dewan yang sewanya mungkin RM120 sejam.","type":"text"}]},{"type":"paragraph","content":[{"text":"Dewan Hamzah lain ceritanya: cagaran kebersihan RM1,500, keselamatan RM1,500 dan pematuhan masa RM1,750.","type":"text"}]},{"type":"paragraph","content":[{"text":"Satu nota kecil yang menjimatkan masa: Dewan Sukan Klang di Seri Andalas tiada dalam jadual kadar itu kerana ia diserahkan kepada syarikat swasta sejak 1 Oktober 2021. Kadar majlis tidak terpakai di situ.","type":"text"}]},{"type":"paragraph","content":[{"text":"(Sumber: senarai kadar sewaan dewan MBDK, mbdk.gov.my, dua dokumen yang sepadan bertarikh Mac dan Disember 2024; jadual cagaran bertanda \"dikemaskini 27/1/2023\", disemak 24 Ogos 2026.)","type":"text","marks":[{"type":"italic"}]}]},{"type":"heading","attrs":{"level":3},"content":[{"text":"Majlis Bandaraya Subang Jaya","type":"text"}]},{"type":"paragraph","content":[{"text":"MBSJ menyusun dewannya dalam lima kategori harga, A hingga E. Sesi majlis lapan jam, sesi persiapan enam jam:","type":"text"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Kategori","type":"text"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Majlis, hari biasa","type":"text"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Majlis, cuti am","type":"text"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Persiapan, hari biasa","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"A (USJ 7)","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"RM3,200","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"RM3,600","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"RM800","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"B (Bandar Kinrara BK5)","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"RM2,400","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"RM2,800","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"RM600","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"C (SS15/4, Puchong Indah, Putra Permai)","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"RM1,440","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"RM2,000","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"RM360","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"D (Seri Kembangan, Laman Puteri 3, Puchong Jaya)","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"RM1,200","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"RM1,760","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"RM300","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"E (Taman Kinrara, Puchong Prima, Batu 3 Subang Jaya)","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"RM880","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"RM1,440","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"RM220","type":"text"}]}]}]}]},{"type":"paragraph","content":[{"text":"Cagaran MBSJ ialah 50% daripada jumlah harga tempahan. Jadi majlis di USJ 7 dengan satu sesi persiapan berjumlah RM4,000, dan cagarannya RM2,000.","type":"text"}]},{"type":"paragraph","content":[{"text":"Ada satu perkara dalam senarai MBSJ yang patut dibaca sebelum memilih. ","type":"text"},{"text":"Harga tidak mengikut saiz.","type":"text","marks":[{"type":"bold"}]},{"text":" Dewan Putra Permai di Seri Kembangan, kategori C pada RM1,440, muat dianggarkan 700 orang. Dewan USJ 7, kategori A pada RM3,200, muat 500 orang. Dan dalam senarai fasiliti rasmi, USJ 7 tersenarai dengan ","type":"text"},{"text":"kipas","type":"text","marks":[{"type":"bold"}]},{"text":", bukan penghawa dingin, sedangkan Dewan Laman Puteri 3 pada RM1,200 tersenarai dengan penghawa dingin.","type":"text"}]},{"type":"paragraph","content":[{"text":"Satu lagi yang jujur disebut: hampir setiap dewan serbaguna MBSJ dalam senarai itu ada gelanggang badminton, dan Dewan Putra Heights (Camelia) ada tiga gelanggang pickleball. Ini dewan sukan yang menerima tempahan kenduri, bukan dewan majlis. Ia berbaloi asalkan anda faham apa yang anda sewa.","type":"text"}]},{"type":"paragraph","content":[{"text":"(Sumber: senarai dewan serbaguna MBSJ, mbsj.gov.my, dokumen bertarikh 23 Februari 2024, disemak 24 Ogos 2026.)","type":"text","marks":[{"type":"italic"}]}]},{"type":"heading","attrs":{"level":3},"content":[{"text":"Majlis Perbandaran Sepang","type":"text"}]},{"type":"paragraph","content":[{"text":"Sepang mengira ikut jam, dan menyiarkan kadar khusus untuk upacara perkahwinan berasingan daripada kadar sukan.","type":"text"}]},{"type":"paragraph","content":[{"text":"Bagi dewan komuniti: dewan 1 dan 2 gelanggang RM100 sejam tanpa penghawa dingin dan RM150 sejam berhawa dingin; dewan 3 gelanggang RM200 sejam tanpa penghawa dingin dan RM250 sejam berhawa dingin. Cagaran RM500 untuk kedua-duanya.","type":"text"}]},{"type":"paragraph","content":[{"text":"Dewan Serbaguna Kelab Komuniti dijual sebagai blok empat jam: RM1,500 hari biasa, RM2,000 pada cuti am, cagaran RM500.","type":"text"}]},{"type":"paragraph","content":[{"text":"Satu syarat yang tiada di majlis lain: penggunaan untuk upacara perkahwinan memerlukan permohonan bertulis dan ulasan atau kelulusan Yang Dipertua. Ia bukan tempahan kaunter biasa. Tempahan dan bayaran pula hanya boleh dibuat di Kaunter Pelbagai MPSepang.","type":"text"}]},{"type":"paragraph","content":[{"text":"(Sumber: mpsepang.gov.my, halaman Kemudahan Awam & Kadar Sewaan, Kemudahan Komuniti & Kebudayaan. Kadar bertanda berkuat kuasa 1 Oktober 2022; disemak 25 Ogos 2026.)","type":"text","marks":[{"type":"italic"}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Dewan besar: bila harga melompat","type":"text"}]},{"type":"paragraph","content":[{"text":"Dua contoh menunjukkan jurang antara dewan komuniti dan dewan majlis sebenar.","type":"text"}]},{"type":"paragraph","content":[{"text":"Di Dewan Banquet, Dewan Sivik MBPJ, minimum satu sesi empat jam ialah RM5,000, dan setiap jam tambahan RM1,000. Cagaran RM2,000, tunai atau bank draf sahaja. Tetapi harga itu datang dengan pakej: 500 kerusi banquet, 50 meja bulat, sistem PA, penghawa dingin, dua mikrofon dan juruteknik bersedia sepanjang majlis.","type":"text"}]},{"type":"paragraph","content":[{"text":"Dewan Hamzah di Klang pula RM3,450 untuk enam jam atau RM7,500 untuk sepuluh jam, penghawa dingin sudah termasuk.","type":"text"}]},{"type":"paragraph","content":[{"text":"Bandingkan dengan dewan komuniti RM160 tadi. Di satu hujung anda menyewa ruang kosong, di hujung yang lain anda menyewa ruang yang sudah siap bermajlis, dan itu menjelaskan sebahagian besar jurang harganya.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Cuti am: bayaran dua kali ganda","type":"text"}]},{"type":"paragraph","content":[{"text":"MBPJ dan MBSJ dua-dua mengenakan kadar lebih tinggi pada cuti umum. MBPJ menyatakannya sebagai ","type":"text"},{"text":"bayaran dua kali ganda","type":"text","marks":[{"type":"bold"}]},{"text":" bagi cuti am yang diisytiharkan Kerajaan Persekutuan dan Negeri Selangor. MBSJ menyiarkan lajur cuti am berasingan: kategori A naik daripada RM3,200 ke RM3,600, kategori E daripada RM880 ke RM1,440.","type":"text"}]},{"type":"paragraph","content":[{"text":"Kalau tarikh anda fleksibel, memindahkan majlis daripada hari cuti ke hujung minggu biasa boleh menjimatkan beberapa ratus hingga beberapa ribu ringgit tanpa mengubah apa-apa lagi.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Yang tidak tersiar, dan apa maknanya","type":"text"}]},{"type":"paragraph","content":[{"text":"Dua pihak berkuasa besar tidak menyiarkan kadar dewan mereka dalam talian, dan kami tidak akan menganggarkannya.","type":"text"}]},{"type":"paragraph","content":[{"text":"DBKL tidak. Portal rasmi dbkl.gov.my menyenaraikan 22 dewan serbaguna dengan nama, alamat dan nombor telefon, dan mengarahkan semua tempahan ke sistem Tempah@KL. Tiada satu pun kadar sewa tersiar di halaman itu.","type":"text"}]},{"type":"paragraph","content":[{"text":"MBSA Shah Alam separuh sahaja. Halaman tempahan dewan-dewan majlis MBSA menerangkan prosedur dan menyenaraikan SOP, tanpa satu pun kadar. Angka sewa dewan majlis MBSA yang beredar di internet datang daripada blog, sebahagiannya bertarikh 2015, dan kami tidak dapat mengesahkan satu pun daripada sumber majlis sendiri.","type":"text"}]},{"type":"paragraph","content":[{"text":"Tetapi Dewan Bankuet MBSA di Wisma MBSA ada kadarnya tersiar penuh, di halaman tempahan yang berasingan: RM7,500 untuk sesi siang 10 pagi hingga 4 petang, RM8,000 untuk sesi malam 5 petang hingga 11 malam, cagaran RM2,000. Skrin LED RM500, penghawa dingin tambahan RM310 sejam. Halaman itu menyatakan kadar tersebut sudah termasuk persiapan empat jam sebelum majlis, bilik VIP dan tempat letak kereta di dalam bangunan Wisma MBSA. Ia juga menyenaraikan enam katerer dengan nama dan nombor telefon.","type":"text"}]},{"type":"paragraph","content":[{"text":"Kalau anda merancang majlis di Kuala Lumpur, atau di dewan majlis MBSA selain Dewan Bankuet, kadar sebenar perlu diambil terus daripada kaunter atau sistem tempahan majlis berkenaan. Angka di blog untuk kawasan ini tidak boleh dipakai untuk bajet.","type":"text"}]},{"type":"paragraph","content":[{"text":"(Sumber: halaman Tempahan Dewan Bankuet dan Tempahan Dewan-Dewan Majlis, mbsa.gov.my, disemak 25 Ogos 2026.)","type":"text","marks":[{"type":"italic"}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Cara menyemak kadar sendiri sebelum bayar","type":"text"}]},{"type":"orderedList","attrs":{"type":null,"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Cari \"kadar sewaan dewan\" bersama nama majlis perbandaran anda. Kebanyakan majlis di Selangor menyiarkan PDF penuh.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Baca semua baris pada baris dewan itu, bukan lajur sewa sahaja. Penghawa dingin, kebersihan, elektrik, sampah dan persiapan selalunya berasingan.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Semak sama ada kadar itu sejam atau sesesi. Ini punca silap paling besar.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Tanya sama ada hari persiapan dikira sebagai tempahan kedua. Di MBSJ ia memang dikira, dan ia menambah RM220 hingga RM800.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Asingkan cagaran daripada kos. Ia kembali, tetapi ia perlu ada dahulu.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Sahkan tarikh dokumen. Kadar MBPJ, MBSJ dan Klang yang tersiar hari ini bertarikh 2024; kadar Sepang berkuat kuasa 1 Oktober 2022.","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Sebelum menandatangani apa-apa, ada senarai soalan yang lebih panjang daripada soal harga: kunci dewan, waktu masuk, siapa mengemas, dan siapa bertanggungjawab kalau sesuatu rosak. Kami kumpulkan semuanya dalam ","type":"text"},{"text":"checklist sewa dewan kahwin","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"/artikel/idea-dan-nasihat/sewa-dewan-kahwin","class":null,"target":"_blank"}}]},{"text":".","type":"text"}]},{"type":"paragraph","content":[{"text":"Dan kalau anda masih memilih tempat, senarai ","type":"text"},{"text":"dewan kahwin murah","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"/artikel/idea-dan-nasihat/dewan-kahwin","class":null,"target":"_blank"}}]},{"text":" di Selangor dan Kuala Lumpur ada di sini.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Ringkasnya","type":"text"}]},{"type":"paragraph","content":[{"text":"Untuk kenduri di dewan komuniti majlis perbandaran, bajet ","type":"text"},{"text":"RM800 hingga RM2,000","type":"text","marks":[{"type":"bold"}]},{"text":" untuk ruang sahaja di kebanyakan kawasan Lembah Klang. Itu sewa, penghawa dingin, kebersihan dan hari persiapan digabung, dan belum termasuk katering, pelamin atau apa-apa hiasan. Tambah ","type":"text"},{"text":"RM700 hingga RM2,000","type":"text","marks":[{"type":"bold"}]},{"text":" lagi sebagai cagaran yang perlu ada di hadapan.","type":"text"}]},{"type":"paragraph","content":[{"text":"Dewan serbaguna besar seperti MBSJ kategori A atau Dewan Banquet MBPJ meletakkan anda pada ","type":"text"},{"text":"RM4,000 hingga RM6,000","type":"text","marks":[{"type":"bold"}]},{"text":" untuk ruang, dan pada tahap itu sebahagian daripada peralatan majlis sudah termasuk.","type":"text"}]},{"type":"paragraph","content":[{"text":"Angka-angka ini ialah kadar tersiar setiap majlis perbandaran pada 25 Ogos 2026. Kadar berubah, dan sesetengah dokumen rasmi sudah lama tidak dikemas kini, jadi sahkan dengan majlis berkenaan sebelum anda kunci bajet.","type":"text"}]},{"type":"figureBlock","attrs":{"alt":"Dewan orang ramai kampung bercat kuning berbumbung zink biru, dengan pagar dawai, dua bendera Malaysia di tiang, dan papan tanda konkrit di sebelah pintu masuk berhampiran jalan berkerikil.","src":"https://images.hellokahwin.com/inspire/harga-sewa-dewan-kahwin/1787652742286-images-s-dewan-orang-ramai-perak-wiki-farazi/high.webp","data-caption":"Dewan orang ramai kampung seperti ini berada di hujung paling murah senarai kadar, sekitar RM60 sejam. Gambar di Kampung Batu 26, Manjung, Perak. — Kredit: Wiki Farazi (CC0)","data-caption-url":"https://commons.wikimedia.org/wiki/File:Dewan_Orang_Ramai_Kampung_Batu_26,_Kampung_Batu_26_20241224_105017.jpg"}}]}'::jsonb,
  cover_image_url = 'https://images.hellokahwin.com/inspire/harga-sewa-dewan-kahwin/1787652742286-images-s-jamuan-kenduri-raja-abd-kadir.jpg',
  cover_image_variants = '{"low":{"url":"https://images.hellokahwin.com/inspire/harga-sewa-dewan-kahwin/1787652742286-images-s-jamuan-kenduri-raja-abd-kadir/low.webp","sizeBytes":57774},"high":{"url":"https://images.hellokahwin.com/inspire/harga-sewa-dewan-kahwin/1787652742286-images-s-jamuan-kenduri-raja-abd-kadir/high.webp","sizeBytes":387264},"original":{"url":"https://images.hellokahwin.com/inspire/harga-sewa-dewan-kahwin/1787652742286-images-s-jamuan-kenduri-raja-abd-kadir.jpg","sizeBytes":2166082}}'::jsonb,
