-- lafaz-taklik  id=a6276a80-a292-45f0-947d-ee9e7ef59783  updated_at was 2026-08-25T10:12:14.292Z
update articles set
  title = 'Lafaz Taklik: Apa Suami Baca Selepas Akad, dan Apa Ertinya',
  excerpt = 'Lafaz taklik ialah perjanjian yang dibuat suami selepas akad. Teks penuhnya diwartakan negeri demi negeri; kami salin versi Perak daripada Warta Kerajaan dan terangkan apa yang isteri perlu buat kalau syaratnya berlaku.',
  content = '{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Lafaz taklik ialah perjanjian yang dilafazkan oleh suami sebaik selepas akad nikah. Isinya satu janji bersyarat: kalau perkara tertentu berlaku, dan isteri mengadu kepada Mahkamah Syariah, dan mahkamah sabitkan aduan itu, maka talak jatuh. Teks penuhnya ditetapkan oleh setiap negeri dalam borang yang diwartakan, jadi ia berbeza mengikut negeri.","type":"text"}]},{"type":"figureBlock","attrs":{"alt":"Grafik tiga syarat taklik dalam borang perakuan nikah Perak: meninggalkan isteri empat bulan qamariah, tidak memberi nafkah empat bulan qamariah, dan menyebabkan mudarat atau darar syarie, dengan nota RM10 dibayar kepada Mahkamah Syariah di bawahnya.","src":"https://images.hellokahwin.com/inspire/lafaz-taklik/1787652720318-cover-lafaz-taklik/high.webp","data-caption":"Tiga syarat dalam lafaz taklik yang diwartakan di Perak, Pk. P.U. 30 bertarikh 1 Jun 2013. — Grafik: HelloKahwin","data-caption-url":null}},{"type":"paragraph","content":[{"text":"Kebanyakan pengantin lelaki membacanya daripada sekeping kertas yang dihulur Pendaftar, sekali seumur hidup, dalam keadaan gementar. Ini apa yang tertulis di situ dan apa yang ia bermakna kemudian.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Takrif dalam enakmen","type":"text"}]},{"type":"paragraph","content":[{"text":"Enakmen Undang-Undang Keluarga Islam (Negeri Selangor) 2003 mentakrifkan taklik sebagai \"lafaz perjanjian yang dibuat oleh suami selepas akad nikah mengikut Hukum Syarak dan peruntukan Enakmen ini\". Takrif yang sama, perkataan demi perkataan, ada dalam Enakmen Undang-Undang Keluarga Islam (Negeri Pulau Pinang) 2004.","type":"text"}]},{"type":"paragraph","content":[{"text":"Dua perkara penting dalam takrif itu. Ia dibuat selepas akad, dan bukan sebahagian daripada akad itu. Dan ia perjanjian, bukan talak: talak hanya jatuh kemudian, kalau syaratnya berlaku dan mahkamah mengesahkannya.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Teks penuh, seperti yang diwartakan di Perak","type":"text"}]},{"type":"paragraph","content":[{"text":"Kaedah-Kaedah Undang-Undang Keluarga Islam (Borang dan Fi) 2013, diwartakan sebagai Pk. P.U. 30 dalam Warta Kerajaan Negeri Perak pada 1 Jun 2013, mencetak lafaz taklik dalam Borang 4 dan Borang 5. Ini teksnya, disalin daripada Warta itu:","type":"text"}]},{"type":"blockquote","content":[{"type":"paragraph","content":[{"text":"Saya (Nama Suami) dengan ini berta''liq bahawa: apabila saya tinggalkan isteri saya (Nama Isteri)","type":"text"}]},{"type":"paragraph","content":[{"text":"(i) Selama empat bulan Qamariah berturut-turut atau lebih sama ada dengan sengaja atau dengan paksa; atau","type":"text"}]},{"type":"paragraph","content":[{"text":"(ii) Jika saya atau wakil saya tidak memberikan nafkah kepadanya selama empat bulan Qamariah berturut-turut atau lebih sedangkan dia taat kepada saya; atau","type":"text"}]},{"type":"paragraph","content":[{"text":"(iii) Jika saya menyebabkan mudarat terhadap tubuh badannya atau kehormatannya atau harta bendanya; atau menyebabkan penganiayaan atau sebarang Darar Syarie;","type":"text"}]},{"type":"paragraph","content":[{"text":"dan kemudian dia mengadu kepada Mahkamah Syariah dan jika sabit aduannya di sisi Hakim Syarie, dan dia memberikan kepada Mahkamah Syariah yang menerima RM10.00 bagi pihak saya, maka pada ketika itu tertalaq dia dengan talaq khulu''.","type":"text"}]}]},{"type":"paragraph","content":[{"text":"Bulan Qamariah ialah bulan mengikut kalendar Hijrah. Darar Syarie ialah kemudaratan yang diiktiraf oleh Hukum Syarak. Talak khulu'' ialah talak tebus.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Tiga syarat itu, dalam bahasa harian","type":"text"}]},{"type":"heading","attrs":{"level":3},"content":[{"text":"Ditinggalkan empat bulan","type":"text"}]},{"type":"paragraph","content":[{"text":"Bukan bergaduh, bukan merajuk seminggu. Empat bulan Qamariah berturut-turut atau lebih, sama ada suami pergi dengan sengaja atau kerana dipaksa.","type":"text"}]},{"type":"heading","attrs":{"level":3},"content":[{"text":"Tidak diberi nafkah empat bulan","type":"text"}]},{"type":"paragraph","content":[{"text":"Syarat ini datang dengan syarat balas dalam teks yang sama: \"sedangkan dia taat kepada saya\". Mahkamah yang menimbang bahagian itu, bukan mana-mana pihak lain.","type":"text"}]},{"type":"heading","attrs":{"level":3},"content":[{"text":"Mudarat","type":"text"}]},{"type":"paragraph","content":[{"text":"Tubuh badan, kehormatan atau harta benda, atau penganiayaan, atau apa-apa Darar Syarie.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Kalau syaratnya berlaku, talak tidak jatuh dengan sendirinya","type":"text"}]},{"type":"paragraph","content":[{"text":"Teksnya sendiri menyebut tiga langkah: isteri mengadu kepada Mahkamah Syariah, Hakim Syarie sabitkan aduan itu, dan RM10 diserahkan kepada Mahkamah bagi pihak suami. Barulah talak berlaku.","type":"text"}]},{"type":"paragraph","content":[{"text":"Enakmen menulisnya sebagai satu prosiding. Seksyen 50 Enakmen Selangor 2003: seorang perempuan yang bersuami boleh, jika berhak mendapat perceraian menurut syarat surat perakuan taklik, memohon kepada Mahkamah untuk menetapkan bahawa perceraian itu telah berlaku. Mahkamah kemudian memeriksa permohonan dan membuat penyiasatan, dan jika berpuas hati perceraian itu sah mengikut Hukum Syarak, mengesahkan dan merekodkannya, lalu menghantar salinan diperakui kepada Pendaftar dan Ketua Pendaftar untuk didaftarkan.","type":"text"}]},{"type":"paragraph","content":[{"text":"Seksyen 50 Enakmen Pulau Pinang 2004 membawa peruntukan yang sama.","type":"text"}]},{"type":"paragraph","content":[{"text":"Di Perak, permohonan itu ada borangnya sendiri: Borang 11, Permohonan untuk Perceraian di Bawah Ta''liq, di bawah seksyen 50, seperti disenaraikan dalam Pk. P.U. 30.","type":"text"}]},{"type":"paragraph","content":[{"text":"Jabatan Mufti Negeri Selangor, menjawab satu soalan dalam sistem e-Musykil mereka pada 2025, menegaskan perkara yang sama: pihak yang berautoriti dalam menentukan sesuatu penceraian itu berlaku atau tidak ialah Mahkamah Syariah.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Ke mana lafaz itu pergi selepas majlis","type":"text"}]},{"type":"paragraph","content":[{"text":"Enakmen menyimpannya di dua tempat.","type":"text"}]},{"type":"paragraph","content":[{"text":"Seksyen 22(1) Enakmen Selangor 2003 menghendaki Pendaftar mencatatkan butir-butir yang ditetapkan \"dan ta’liq yang ditetapkan atau ta’liq lain\" bagi perkahwinan itu dalam Daftar Perkahwinan, sebaik selepas akad. Peruntukan yang sama ada dalam seksyen 22 Enakmen Pulau Pinang 2004.","type":"text"}]},{"type":"paragraph","content":[{"text":"Seksyen 26(2) kedua-dua enakmen itu pula menghendaki Pendaftar mengeluarkan surat perakuan taklik dalam borang yang ditetapkan kepada setiap satu pihak, selepas fi yang ditetapkan dibayar. Isteri sepatutnya memegang satu salinan. Kalau anda tidak pernah menerimanya, itu soalan untuk Pejabat Agama Daerah anda.","type":"text"}]},{"type":"paragraph","content":[{"text":"Di Perak, Borang 5 ialah Perakuan Nikah di bawah seksyen 26, dan Warta mencetak fi RM15.00 pada borang itu.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"\"Taklik yang ditetapkan atau taklik lain\"","type":"text"}]},{"type":"paragraph","content":[{"text":"Frasa itu datang daripada seksyen 22(1). Yang dicetak dalam borang ialah taklik yang ditetapkan, versi lalai yang dibaca oleh hampir semua orang. Enakmen membenarkan taklik lain dicatatkan.","type":"text"}]},{"type":"paragraph","content":[{"text":"Kami tidak menemui mana-mana jabatan yang menerbitkan panduan awam tentang bagaimana pasangan boleh mencadangkan taklik lain, atau apa yang diterima. Kalau ini yang anda cari, tanya Pendaftar atau Pejabat Agama Daerah anda sebelum tarikh akad, bukan pada hari itu.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Kenapa versi negeri anda mungkin berbeza","type":"text"}]},{"type":"paragraph","content":[{"text":"Lafaz taklik ditetapkan dalam kaedah yang diwartakan oleh setiap negeri, bukan dalam satu dokumen kebangsaan. Perak menetapkannya melalui Pk. P.U. 30 (2013), yang dibuat di bawah subseksyen 135(3) Enakmen Undang-Undang Keluarga Islam (Perak) 2004.","type":"text"}]},{"type":"paragraph","content":[{"text":"Kami menyalin teks Perak kerana kami membacanya sendiri dalam Warta. Kami tidak menyalin teks negeri lain, kerana kami tidak menemui satu tempat rasmi yang menghimpunkan keempat belas versi itu, dan meneka satu bukan pilihan pada halaman seperti ini. Angka RM10 dan istilah talak khulu'' dalam petikan di atas datang daripada teks Perak, dan tidak boleh dianggap sama di negeri lain.","type":"text"}]},{"type":"paragraph","content":[{"text":"Cara paling pantas untuk melihat versi negeri anda: surat perakuan nikah anda sendiri. Ia tercetak di situ.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Sumber","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Kaedah-Kaedah Undang-Undang Keluarga Islam (Borang dan Fi) 2013, Pk. P.U. 30. Warta Kerajaan Negeri Perak, Jil. 66, Tambahan No. 13, 1 Jun 2013. Borang 1 hingga 19, termasuk Borang 4, Borang 5 dan Borang 11. Diterbitkan oleh Jabatan Kehakiman Syariah Negeri Perak. Disemak 24 Ogos 2026.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Enakmen Undang-Undang Keluarga Islam (Negeri Selangor) 2003, seksyen 2, 22, 26 dan 50. Warta Kerajaan Negeri Selangor, 27 Julai 2003, diterbitkan oleh Jabatan Kehakiman Syariah Negeri Selangor. Disemak 24 Ogos 2026.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Enakmen Undang-Undang Keluarga Islam (Negeri Pulau Pinang) 2004, seksyen 2, 22, 26 dan 50. Jabatan Kehakiman Syariah Negeri Pulau Pinang. Disemak 24 Ogos 2026.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Jabatan Mufti Negeri Selangor, sistem e-Musykil, jawapan bank soalan id 7304 (kategori Munakahat, Tahun Soalan 2025) mengenai taklik talak. Disemak 25 Ogos 2026.","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Halaman ini melaporkan apa yang tertulis dalam Warta dan apa yang jabatan agama nyatakan. Ia bukan nasihat guaman dan bukan fatwa. Kalau taklik anda mungkin sudah berlaku, bawa surat perakuan taklik anda ke Mahkamah Syariah negeri anda.","type":"text"}]}]}'::jsonb,
  cover_image_url = 'https://images.hellokahwin.com/inspire/lafaz-taklik/1787652720318-images-s-lelaki-menadah-doa-ahmad-ali-karim.jpg',
  cover_image_variants = '{"low":{"url":"https://images.hellokahwin.com/inspire/lafaz-taklik/1787652720318-images-s-lelaki-menadah-doa-ahmad-ali-karim/low.webp","sizeBytes":22886},"high":{"url":"https://images.hellokahwin.com/inspire/lafaz-taklik/1787652720318-images-s-lelaki-menadah-doa-ahmad-ali-karim/high.webp","sizeBytes":127782},"original":{"url":"https://images.hellokahwin.com/inspire/lafaz-taklik/1787652720318-images-s-lelaki-menadah-doa-ahmad-ali-karim.jpg","sizeBytes":7335703}}'::jsonb,
