-- pakej-dewan-kahwin  id=250da087-60ec-456f-bf98-f8250bddc275  updated_at was 2026-08-25T10:13:07.918Z
update articles set
  title = 'Pakej Dewan Kahwin: Apa yang Termasuk, dan Apa yang Selalu Tak Termasuk',
  excerpt = 'Perkataan pakej boleh bermakna 500 kerusi dan juruteknik, atau boleh bermakna kunci dan bilik kosong. Ini cara membaca perbezaannya sebelum membayar deposit.',
  content = '{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Perkataan \"pakej\" tidak bermakna benda yang sama di dua dewan. Di Dewan Banquet, Dewan Sivik MBPJ, pakej bermakna 500 kerusi banquet, 50 meja bulat, sistem PA, penghawa dingin, dua mikrofon dan juruteknik yang bersedia sepanjang majlis. Di dewan komuniti pada RM160 satu sesi, pakej bermakna ruang dan kunci. Perbezaan itu boleh bernilai beberapa ribu ringgit, dan ia jarang dinyatakan dengan jelas sebelum deposit dibayar.","type":"text"}]},{"type":"figureBlock","attrs":{"alt":"Kad tajuk artikel bertajuk Pakej Dewan Kahwin, apa yang termasuk dan apa yang tidak, di atas latar krim dengan garis tembaga.","src":"https://images.hellokahwin.com/inspire/pakej-dewan-kahwin/1787652775377-c6-2-a3-pakej-dewan-kahwin-cover/high.webp","data-caption":"Grafik: HelloKahwin","data-caption-url":null}},{"type":"paragraph","content":[{"text":"Artikel ini menunjukkan satu pakej dewan yang benar-benar tersiar secara rasmi, baris demi baris, supaya anda tahu apa yang perlu ditanya tentang mana-mana pakej lain.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Satu pakej sebenar, dibuka baris demi baris","type":"text"}]},{"type":"paragraph","content":[{"text":"Majlis Bandaraya Petaling Jaya menyiarkan kandungan pakej Dewan Banquet-nya secara terperinci. Ia jarang berlaku, dan ia berguna sebagai ukuran.","type":"text"}]},{"type":"paragraph","content":[{"text":"Harganya: minimum satu sesi empat jam RM5,000. Setiap jam tambahan RM1,000. Cagaran RM2,000, tunai atau bank draf sahaja.","type":"text"}]},{"type":"heading","attrs":{"level":4},"content":[{"text":"Yang termasuk dalam harga itu","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"500 kerusi banquet, tanpa sarung kerusi","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"50 meja bulat, tanpa alas meja","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Sistem PA","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Penghawa dingin","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Dua mikrofon","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Juruteknik bersedia","type":"text"}]}]}]},{"type":"heading","attrs":{"level":4},"content":[{"text":"Yang tidak termasuk, dan berapa harganya","type":"text"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Tambahan","type":"text"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Kadar","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Kerusi banquet tambahan","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"RM6 seunit","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Meja bulat tambahan","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"RM10 seunit","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Meja 3 kaki x 6 kaki","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"RM5 seunit","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Mikrofon tambahan","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"RM50 seunit","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Projektor","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"RM400 sekali guna","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Bilik tetamu","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"RM200 sekali guna","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Rostrum","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"RM50 sekali guna","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Skrin LED","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"RM800 sekali guna","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Persiapan, tanpa penghawa dingin","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"RM300 sejam","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Persiapan, dengan penghawa dingin","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"RM600 sejam","type":"text"}]}]}]}]},{"type":"paragraph","content":[{"text":"Baca dua baris terakhir sekali lagi. Masa persiapan bukan sebahagian daripada pakej. Kalau pelamin anda perlu enam jam untuk dipasang dan anda mahu dewan itu sejuk semasa kru bekerja, itu RM3,600 di atas RM5,000 tadi. Kalau tanpa penghawa dingin, RM1,800.","type":"text"}]},{"type":"paragraph","content":[{"text":"Dan satu syarat pada baris yang sama: persiapan hanya dibenarkan pada hari yang sama dengan tarikh tempahan. Tiada pemasangan malam sebelum. Beritahu pihak hiasan awal, kerana ia menentukan berapa lama mereka ada.","type":"text"}]},{"type":"paragraph","content":[{"text":"Dan satu lagi baris: bayaran dua kali ganda dikenakan bagi cuti am yang diisytiharkan Kerajaan Persekutuan dan Negeri Selangor.","type":"text"}]},{"type":"paragraph","content":[{"text":"(Sumber: senarai kadar sewaan Dewan Banquet, Dewan Sivik MBPJ, tahun 2024, tersiar di mbpj.gov.my, disemak 25 Ogos 2026.)","type":"text","marks":[{"type":"italic"}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Dua perkataan yang sering dikelirukan","type":"text"}]},{"type":"paragraph","content":[{"text":"Mulakan dengan sarung kerusi dan alas meja. Senarai MBPJ menyatakan \"tanpa sarung kerusi\" dan \"tanpa alas meja\" dua kali. Ini bukan butiran kecil. Lima ratus kerusi banquet tanpa sarung kelihatan seperti dewan mesyuarat, bukan majlis kahwin. Sarung dan alas biasanya datang daripada pihak hiasan atau katerer, dan ia dikira berasingan.","type":"text"}]},{"type":"paragraph","content":[{"text":"Kemudian pakej siaraya. MBSJ menyiarkan \"pakej siaraya\" pada RM500 untuk sesi empat jam, berasingan daripada sewa dewan. Jadi sistem bunyi tidak semestinya termasuk hanya kerana dewan itu ada pentas.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Syarat katerer: bahagian yang benar-benar mengikat","type":"text"}]},{"type":"paragraph","content":[{"text":"Ini yang paling kerap dilangkau, dan ia menentukan berapa yang anda boleh jimat.","type":"text"}]},{"type":"paragraph","content":[{"text":"Syarat am penggunaan Dewan Banquet MBPJ menyatakan dengan jelas:","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Penempah dibenarkan menyediakan makanan secara hidang (dome) dan buffet.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Penempah hanya dibenarkan menggunakan katerer yang mahir dan diiktiraf.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Semua pelayan hendaklah berpakaian kemas, berseragam dan terlatih.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Makanan yang ditanggung halal sahaja dibenarkan.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Segala penggunaan yang berunsurkan air dan api tidak dibenarkan.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Tidak dibenarkan memasak di dalam mahupun di luar dewan.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Tidak dibenarkan membawa makanan atau barang dari luar kecuali dengan surat kebenaran daripada pihak Majlis.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Dilarang merokok dan membawa minuman beralkohol.","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Baris \"tidak dibenarkan memasak di dalam dan di luar dewan\" ialah yang paling mahal. Ia bermakna masakan kampung di belakang dewan, cara paling murah untuk memberi makan tiga ratus orang, tidak dibenarkan di dewan ini. Makanan mesti sampai sudah siap.","type":"text"}]},{"type":"paragraph","content":[{"text":"Setiap dewan mempunyai syarat sendiri, dan syarat ini berbeza antara dewan dalam majlis perbandaran yang sama. Ia perlu ditanya sebelum anda memilih katerer, bukan selepas.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Apa yang perlu ditanya tentang mana-mana pakej","type":"text"}]},{"type":"paragraph","content":[{"text":"Gunakan senarai MBPJ di atas sebagai templat, dan minta pihak dewan menjawab setiap satu secara bertulis:","type":"text"}]},{"type":"orderedList","attrs":{"type":null,"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Berapa jam dalam harga asas, dan berapa jam tambahan?","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Berapa meja dan kerusi termasuk, dan adakah sarung serta alas termasuk?","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Adakah sistem bunyi termasuk, atau ia pakej berasingan?","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Adakah penghawa dingin termasuk, atau dikira sejam?","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Adakah masa persiapan termasuk? Kalau tidak, berapa sejam, dan adakah penghawa dingin semasa persiapan dikira berasingan lagi?","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Berapa cagaran, dalam bentuk apa, dan bila ia dipulangkan?","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Adakah kadar berganda pada cuti am?","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Bolehkah saya bawa katerer sendiri, dan adakah senarai katerer yang diluluskan?","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Bolehkah masak di premis?","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Siapa membuang sampah, dan adakah caj sampah berasingan?","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Sembilan daripada sepuluh soalan itu tidak boleh dijawab daripada laman web. Ia perlu ditanya, dan jawapannya perlu ada dalam surat kelulusan tempahan anda.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Kalau pakej itu terlalu murah","type":"text"}]},{"type":"paragraph","content":[{"text":"Dewan komuniti kecil yang tersiar pada RM160 hingga RM250 satu sesi hampir tidak pernah datang dengan meja, kerusi bersarung, sistem bunyi atau juruteknik. Itulah sebabnya harganya begitu. Cuma bajet anda perlu menampung sewaan meja, kerusi dan sistem bunyi daripada pembekal lain, dan jumlahnya boleh melebihi sewa dewan itu sendiri.","type":"text"}]},{"type":"paragraph","content":[{"text":"Bandingkan dua-dua cara sebagai jumlah, bukan sebagai sewa. Kadangkala dewan yang lebih mahal dengan pakej penuh keluar lebih murah, dan kadangkala tidak.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Pakej dewan kahwin di Shah Alam","type":"text"}]},{"type":"paragraph","content":[{"text":"Shah Alam ada satu pakej yang tersiar penuh, dan selebihnya tidak.","type":"text"}]},{"type":"paragraph","content":[{"text":"Yang tersiar ialah Dewan Bankuet MBSA di Wisma MBSA, Seksyen 14. Halaman tempahannya menyenaraikan kadar begini:","type":"text"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Sesi","type":"text"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Masa","type":"text"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Kadar","type":"text"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Cagaran","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Siang","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"10.00 pagi hingga 4.00 petang","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"RM7,500","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"RM2,000","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Malam","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"5.00 petang hingga 11.00 malam","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"RM8,000","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"RM2,000","type":"text"}]}]}]}]},{"type":"paragraph","content":[{"text":"Tambahan pilihan: skrin LED RM500, penghawa dingin tambahan RM310 sejam.","type":"text"}]},{"type":"paragraph","content":[{"text":"Baca satu ayat pada halaman itu dengan teliti, kerana ia mengubah perbandingan sepenuhnya: kadar sewa yang dikenakan sudah termasuk persiapan empat jam sebelum majlis, bilik VIP, dan tempat letak kereta di dalam bangunan Wisma MBSA. Di Dewan Banquet MBPJ, empat jam persiapan berhawa dingin dikira berasingan pada RM600 sejam, iaitu RM2,400. Jadi jurang antara RM5,000 dan RM7,500 lebih rapat daripada yang kelihatan.","type":"text"}]},{"type":"paragraph","content":[{"text":"Halaman itu juga menyenaraikan enam katerer dengan nama, alamat dan nombor telefon. Tanya sama ada senarai itu wajib atau cadangan sebelum anda berbincang dengan katerer lain.","type":"text"}]},{"type":"paragraph","content":[{"text":"Yang tidak tersiar ialah dewan-dewan majlis MBSA yang lain. Halaman tempahan dewan-dewan majlis menerangkan prosedur dan menyenaraikan SOP untuk aktiviti termasuk majlis perkahwinan, tetapi tanpa satu pun kadar. Angka sewa dewan majlis MBSA yang beredar di internet datang daripada blog, sebahagiannya bertarikh 2015, dan kami tidak dapat mengesahkan satu pun daripada MBSA sendiri. Untuk dewan-dewan itu, kadar perlu diambil terus daripada Jabatan Penilaian dan Pengurusan Harta MBSA di Wisma MBSA.","type":"text"}]},{"type":"paragraph","content":[{"text":"Kalau anda mahu melihat tempat-tempat majlis di kawasan itu dahulu, senarai ","type":"text"},{"text":"lokasi majlis kahwin di Shah Alam","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"/artikel/idea-dan-nasihat/majlis-kahwin","class":null,"target":"_blank"}}]},{"text":" ada di sini.","type":"text"}]},{"type":"paragraph","content":[{"text":"(Sumber: halaman Tempahan Dewan Bankuet dan halaman Tempahan Dewan-Dewan Majlis, mbsa.gov.my, disemak 25 Ogos 2026.)","type":"text","marks":[{"type":"italic"}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Ringkasnya","type":"text"}]},{"type":"paragraph","content":[{"text":"Pakej dewan yang benar-benar lengkap wujud, dan ia kelihatan seperti Dewan Banquet MBPJ: RM5,000 untuk empat jam, dengan kerusi, meja, bunyi, penghawa dingin dan juruteknik di dalamnya, dan senarai tambahan yang tersiar terbuka.","type":"text"}]},{"type":"paragraph","content":[{"text":"Selebihnya berada di antara dua hujung, dan satu-satunya cara mengetahui letaknya ialah bertanya sepuluh soalan di atas sebelum membayar deposit. Senarai soalan yang lebih penuh, termasuk soal kunci, waktu masuk dan tanggungjawab kerosakan, ada dalam ","type":"text"},{"text":"checklist sewa dewan kahwin","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"/artikel/idea-dan-nasihat/sewa-dewan-kahwin","class":null,"target":"_blank"}}]},{"text":".","type":"text"}]}]}'::jsonb,
  cover_image_url = 'https://images.hellokahwin.com/inspire/pakej-dewan-kahwin/1787652775377-images-s-pasangan-dan-keluarga-pelamin-mohd-hasan.jpg',
  cover_image_variants = '{"low":{"url":"https://images.hellokahwin.com/inspire/pakej-dewan-kahwin/1787652775377-images-s-pasangan-dan-keluarga-pelamin-mohd-hasan/low.webp","sizeBytes":60734},"high":{"url":"https://images.hellokahwin.com/inspire/pakej-dewan-kahwin/1787652775377-images-s-pasangan-dan-keluarga-pelamin-mohd-hasan/high.webp","sizeBytes":455606},"original":{"url":"https://images.hellokahwin.com/inspire/pakej-dewan-kahwin/1787652775377-images-s-pasangan-dan-keluarga-pelamin-mohd-hasan.jpg","sizeBytes":2865817}}'::jsonb,
