-- rukun-nikah  id=c11fcb8a-734c-4af5-9eec-0bcc02d0347a  updated_at was 2026-08-25T10:11:47.809Z
update articles set
  title = 'Rukun Nikah: 5 Rukun dan Apa Yang Membatalkannya',
  excerpt = 'Lima rukun nikah mengikut senarai Masjid Wilayah Persekutuan, susunan wali sepenuhnya daripada Jabatan Mufti Wilayah Persekutuan, dan apa yang enakmen negeri kata tentang siapa yang boleh mengakadnikahkan.',
  content = '{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Rukun nikah ada lima: lelaki bakal suami, perempuan bakal isteri, wali, dua orang saksi lelaki, dan sighah iaitu ijab dan qabul. Kalau satu daripada lima ini tiada, akad itu tidak menjadi. Senarai ini diterbitkan oleh Masjid Wilayah Persekutuan, di bawah Jabatan Agama Islam Wilayah Persekutuan.","type":"text"}]},{"type":"figureBlock","attrs":{"alt":"Grafik lima rukun nikah disusun menegak: lelaki bakal suami, perempuan bakal isteri, wali, dua orang saksi lelaki, dan sighah ijab dan qabul, setiap satu bernombor satu hingga lima.","src":"https://images.hellokahwin.com/inspire/rukun-nikah/1787652689924-cover-rukun-nikah/high.webp","data-caption":"Lima rukun nikah mengikut senarai Masjid Wilayah Persekutuan. — Grafik: HelloKahwin","data-caption-url":null}},{"type":"paragraph","content":[{"text":"Rukun bermaksud tiang. Ia bahagian yang membentuk akad itu sendiri, bukan syarat tambahan di sekelilingnya. Sebab itu senarainya pendek dan tetap.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Lima rukun nikah","type":"text"}]},{"type":"paragraph","content":[{"text":"Ini senarai penuh, seperti yang tersiar di laman Masjid Wilayah Persekutuan (disemak 24 Ogos 2026):","type":"text"}]},{"type":"orderedList","attrs":{"type":null,"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Lelaki, calon suami","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Perempuan, calon isteri","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Wali","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Dua orang saksi (lelaki)","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Sighah (ijab dan qabul)","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"1. Lelaki, bakal suami","type":"text"}]},{"type":"paragraph","content":[{"text":"Orangnya mesti tertentu. Maksudnya, akad itu menyebut lelaki yang mana, bukan \"sesiapa\" atau \"anak Pak Samad\" tanpa nama.","type":"text"}]},{"type":"paragraph","content":[{"text":"Laman Masjid Wilayah Persekutuan menyenaraikan tujuh syarat bagi pihak lelaki: Islam, bukan mahram dengan bakal isterinya, bukan dalam ihram, tertentu orangnya, berkemampuan zahir dan batin, tidak beristeri empat, dan tidak dipaksa.","type":"text"}]},{"type":"paragraph","content":[{"text":"Mahram di sini bermaksud orang yang haram dikahwini kerana pertalian darah, pertalian kahwin atau susuan.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"2. Perempuan, bakal isteri","type":"text"}]},{"type":"paragraph","content":[{"text":"Enam syarat disenaraikan oleh laman yang sama: Islam, bukan mahram dengan suaminya, bukan dalam ihram, tertentu orangnya, bukan isteri orang, dan bukan dalam iddah.","type":"text"}]},{"type":"paragraph","content":[{"text":"Iddah ialah tempoh menunggu selepas bercerai atau kematian suami. Enakmen negeri mengikat perkara ini pada dokumen: di Selangor, seksyen 14 Enakmen Undang-Undang Keluarga Islam (Negeri Selangor) 2003 menetapkan seorang janda tidak boleh berkahwin melainkan dia mengemukakan surat perakuan cerai yang sah, atau salinan diperakui catatan penceraiannya, atau perakuan daripada Hakim Syarie bahawa dia memang seorang janda.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"3. Wali","type":"text"}]},{"type":"paragraph","content":[{"text":"Wali ialah pihak yang mengakadnikahkan perempuan itu. Tanpa wali, tiada akad.","type":"text"}]},{"type":"paragraph","content":[{"text":"Seksyen 7 Enakmen Selangor 2003 menyatakan perkahwinan di Selangor hendaklah diakadnikahkan mengikut Hukum Syarak oleh wali di hadapan Pendaftar, atau oleh wakil wali di hadapan dan dengan kebenaran Pendaftar, atau sebagai wakil wali. Seksyen 7(2) pula: kalau perempuan itu tiada wali dari nasab, perkahwinan itu hendaklah diakadnikahkan hanya oleh wali Raja.","type":"text"}]},{"type":"paragraph","content":[{"text":"Enakmen yang sama mentakrifkan wali Raja sebagai wali yang ditauliahkan oleh Sultan Selangor bagi Negeri Selangor; oleh Yang di-Pertuan Agong bagi Wilayah Persekutuan, Melaka, Pulau Pinang, Sabah dan Sarawak; dan oleh Raja bagi negeri-negeri lain, untuk mengahwinkan perempuan yang tidak mempunyai wali dari nasab.","type":"text"}]},{"type":"heading","attrs":{"level":3},"content":[{"text":"Susunan wali, dari yang terdekat","type":"text"}]},{"type":"paragraph","content":[{"text":"Jabatan Mufti Wilayah Persekutuan menyenaraikan susunan wali perempuan yang sah mengikut Hukum Syarak dalam Irsyad Hukum Siri ke-408 (7 Februari 2020), dengan rujukan kepada kitab al-Mu''tamad fi al-Fiqh al-Syafi''e. Ini senarainya, ikut turutan:","type":"text"}]},{"type":"paragraph","content":[{"text":"bapa kandung · datuk sebelah bapa ke atas · adik beradik lelaki seibu sebapa · adik beradik lelaki sebapa · anak saudara lelaki seibu sebapa · anak saudara lelaki sebapa · anak lelaki kepada anak saudara lelaki seibu sebapa · anak lelaki kepada anak saudara lelaki sebapa · bapa saudara sebelah bapa seibu sebapa · bapa saudara sebelah bapa sebapa · datuk saudara sebelah bapa seibu sebapa dengan datuknya · datuk saudara sebelah bapa sebapa dengan datuknya · moyang saudara sebelah bapa seibu sebapa dengan moyangnya · moyang saudara sebelah bapa sebapa dengan moyangnya · sepupu lelaki sebelah bapa seibu sebapa · sepupu lelaki sebelah bapa sebapa · cucu lelaki bapa saudara sebelah bapa seibu sebapa · cucu lelaki bapa saudara sebelah bapa sebapa · anak datuk saudara sebelah bapa seibu sebapa dengan datuknya · anak datuk saudara sebelah bapa sebapa dengan datuknya · wali hakim.","type":"text"}]},{"type":"paragraph","content":[{"text":"Yang paling hampir dipanggil wali aqrab. Yang seterusnya dipanggil wali ab''ad.","type":"text"}]},{"type":"heading","attrs":{"level":3},"content":[{"text":"Bila wali hakim boleh ambil tempat","type":"text"}]},{"type":"paragraph","content":[{"text":"Irsyad Hukum yang sama menyenaraikan empat keadaan: wali enggan mengahwinkan tanpa sebab yang munasabah, tiada wali nasab langsung, wali aqrab tidak cukup syarat menjadi wali dan tiada wali ab''ad, atau wali aqrab berada lebih dua marhalah jauhnya atau sedang berihram haji atau umrah.","type":"text"}]},{"type":"paragraph","content":[{"text":"Jabatan Mufti Wilayah Persekutuan menyebut juga bahawa kalau wali aqrab berada kurang dua marhalah, hakim tidak boleh melaksanakan perkahwinan itu kecuali dengan izin wali.","type":"text"}]},{"type":"paragraph","content":[{"text":"Di pihak undang-undang negeri, seksyen 13 Enakmen Selangor 2003 meletakkan pintu itu di tangan Hakim Syarie. Persetujuan untuk perkahwinan diakadnikahkan oleh wali Raja boleh diberi jika perempuan itu tiada wali dari nasab, atau wali tidak dapat ditemui, atau wali enggan memberikan persetujuannya tanpa sebab yang mencukupi, selepas penyiasatan wajar di hadapan semua pihak.","type":"text"}]},{"type":"paragraph","content":[{"text":"Jabatan Mufti Pulau Pinang, menjawab satu soalan dalam sistem eKemusykilan mereka, menyatakan perkahwinan yang menggunakan wali hakim yang dilantik oleh sindiket dan tidak ditauliahkan secara rasmi adalah tidak sah di sisi syarak dan undang-undang, dan pasangan itu wajib mengulangi akad nikah dengan wali yang sah.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"4. Dua orang saksi lelaki","type":"text"}]},{"type":"paragraph","content":[{"text":"Senarai Masjid Wilayah Persekutuan menyebut dua orang saksi, dan menyatakan lelaki.","type":"text"}]},{"type":"paragraph","content":[{"text":"Enakmen negeri meletakkan saksi itu dalam borang juga. Seksyen 22(2) Enakmen Selangor 2003 menghendaki catatan dalam Daftar Perkahwinan diakusaksi oleh kedua-dua pihak, oleh wali, dan oleh dua orang saksi selain daripada Pendaftar, yang hadir semasa perkahwinan itu diakadnikahkan. Peruntukan yang sama ada dalam seksyen 22 Enakmen Undang-Undang Keluarga Islam (Negeri Pulau Pinang) 2004.","type":"text"}]},{"type":"paragraph","content":[{"text":"Jadi dua saksi itu bukan sekadar hadir. Mereka menandatangani.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"5. Sighah: ijab dan qabul","type":"text"}]},{"type":"paragraph","content":[{"text":"Sighah ialah lafaz. Ijab daripada pihak wali, qabul daripada pihak lelaki. Ia rukun kelima, dan ia yang menjadikan empat rukun sebelum ini satu akad.","type":"text"}]},{"type":"paragraph","content":[{"text":"Kadar mas kahwin biasanya diserahkan pada ketika ini. Seksyen 21(1) Enakmen Selangor 2003 menyebut mas kahwin hendaklah biasanya dibayar oleh pihak lelaki atau wakilnya kepada pihak perempuan atau wakilnya di hadapan orang yang mengakadnikahkan perkahwinan itu dan sekurang-kurangnya dua orang saksi lain. Kadar minimum berbeza ikut negeri, dan enam daripada empat belas bidang kuasa tidak menetapkan satu pun. Itu diceritakan penuh dalam ","type":"text"},{"text":"mas kahwin ikut negeri","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"/artikel/hantaran-mas-kahwin/mas-kahwin-ikut-negeri","class":null,"target":"_blank"}}]},{"text":".","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Kalau satu rukun tidak cukup","type":"text"}]},{"type":"paragraph","content":[{"text":"Seksyen 11 Enakmen Selangor 2003 menyebutnya dalam satu ayat: \"Sesuatu perkahwinan adalah tak sah melainkan jika cukup semua syarat yang perlu, menurut Hukum Syarak, untuk menjadikannya sah.\"","type":"text"}]},{"type":"paragraph","content":[{"text":"Enakmen tidak menyenaraikan rukun itu sendiri. Ia menyerahkan soal itu kepada Hukum Syarak, dan menetapkan yang lain: umur, kebenaran, tempat, pendaftaran. Sebab itu senarai rukun datang daripada jabatan agama dan jabatan mufti, manakala syarat pendaftaran datang daripada enakmen negeri.","type":"text"}]},{"type":"paragraph","content":[{"text":"Kalau anda sudah diberitahu ada sesuatu yang tidak kena dengan akad anda, tempat untuk selesaikannya ialah Mahkamah Syariah negeri anda, bukan perbincangan keluarga. Mahkamah yang mengesahkan sama ada sesuatu perkahwinan itu wujud atau tidak.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Rukun cukup tidak bermakna sudah berdaftar","type":"text"}]},{"type":"paragraph","content":[{"text":"Ini dua perkara berasingan, dan ia punca kekeliruan paling kerap dalam bab ini. Rukun yang cukup menjadikan akad itu sah di sisi syarak. Pendaftaran pula urusan enakmen negeri, dengan borang, fi dan tarikh tutupnya sendiri.","type":"text"}]},{"type":"paragraph","content":[{"text":"Selengkapnya ada dalam kluster ","type":"text"},{"text":"rukun, syarat & sah nikah","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"/artikel/rukun-syarat-sah-nikah","class":null,"target":"_blank"}}]},{"text":" dan ","type":"text"},{"text":"borang & pendaftaran nikah","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"/artikel/borang-pendaftaran-nikah","class":null,"target":"_blank"}}]},{"text":".","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Sumber","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Masjid Wilayah Persekutuan, Jabatan Agama Islam Wilayah Persekutuan. \"Rukun Nikah / Syarat Dua Orang Saksi / Syarat Bagi Perempuan\". Disemak 24 Ogos 2026.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Jabatan Mufti Wilayah Persekutuan. Irsyad Hukum Siri ke-408: Hukum Nikah Menggunakan Wali Hakim Walaupun Ada Wali Nasab, 7 Februari 2020. Disemak 24 Ogos 2026.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Enakmen Undang-Undang Keluarga Islam (Negeri Selangor) 2003, seksyen 7, 11, 13, 14, 21 dan 22. Teks Warta Kerajaan Negeri Selangor, 27 Julai 2003, diterbitkan oleh Jabatan Kehakiman Syariah Negeri Selangor. Disemak 24 Ogos 2026.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Enakmen Undang-Undang Keluarga Islam (Negeri Pulau Pinang) 2004, seksyen 22. Diterbitkan oleh Jabatan Kehakiman Syariah Negeri Pulau Pinang. Disemak 24 Ogos 2026.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Jabatan Mufti Pulau Pinang, Sistem eKemusykilan, jawapan 01174. Disemak 24 Ogos 2026.","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Enakmen berbeza mengikut negeri. Yang dipetik di sini Selangor dan Pulau Pinang. Untuk negeri lain, rujuk enakmen negeri anda atau Jabatan Agama Islam negeri.","type":"text"}]},{"type":"figureBlock","attrs":{"alt":"Pengantin lelaki berbaju melayu putih dan bersongkok duduk di sebelah pengantin perempuan berbaju nikah putih bertudung labuh, memegang jambangan bunga ros oren, di hadapan kain latar putih selepas majlis akad nikah.","src":"https://images.hellokahwin.com/inspire/rukun-nikah/1787652689924-images-s-pengantin-selepas-akad-azlan-dupree/high.webp","data-caption":"Sighah, iaitu ijab dan qabul, ialah rukun kelima. Selepas lafaz itu selesai, akad sudah menjadi. — Kredit: Azlan DuPree (CC BY 2.0)","data-caption-url":"https://commons.wikimedia.org/wiki/File:Malay_couple.jpg"}}]}'::jsonb,
  cover_image_url = 'https://images.hellokahwin.com/inspire/rukun-nikah/1787652689924-images-s-akad-nikah-masjid-azlan-dupree.jpg',
  cover_image_variants = '{"low":{"url":"https://images.hellokahwin.com/inspire/rukun-nikah/1787652689924-images-s-akad-nikah-masjid-azlan-dupree/low.webp","sizeBytes":89524},"high":{"url":"https://images.hellokahwin.com/inspire/rukun-nikah/1787652689924-images-s-akad-nikah-masjid-azlan-dupree/high.webp","sizeBytes":489896},"original":{"url":"https://images.hellokahwin.com/inspire/rukun-nikah/1787652689924-images-s-akad-nikah-masjid-azlan-dupree.jpg","sizeBytes":6083749}}'::jsonb,
  cover_image_smart_crops = '{"crop-16x9-og":{"url":"https://images.hellokahwin.com/inspire/rukun-nikah/1787652689924-images-s-akad-nikah-masjid-azlan-dupree/crop-16x9-og.webp?v=0.1867_0.5580-g48c0b959","width":1200,"height":630},"crop-4x3-article-card":{"url":"https://images.hellokahwin.com/inspire/rukun-nikah/1787652689924-images-s-akad-nikah-masjid-azlan-dupree/crop-4x3-article-card.webp?v=0.1867_0.5580-g48c0b959","width":1600,"height":1200},"crop-4x5-mobile-cover":{"url":"https://images.hellokahwin.com/inspire/rukun-nikah/1787652689924-images-s-akad-nikah-masjid-azlan-dupree/crop-4x5-mobile-cover.webp?v=0.1867_0.5580-g48c0b959","width":1843,"height":2304},"crop-4.3x1-desktop-hero":{"url":"https://images.hellokahwin.com/inspire/rukun-nikah/1787652689924-images-s-akad-nikah-masjid-azlan-dupree/crop-4.3x1-desktop-hero.webp?v=0.1867_0.5580-g48c0b959","width":2464,"height":700}}'::jsonb,
